/**
 * @veritasacta/artifacts — Type definitions
 * Supports both v1 (flat) and v2 (structured envelope) artifact formats.
 */

// ── Canonical Serialization ─────────────────────────────────────

/** Produce a deterministic JSON string with sorted keys (JCS-style). ASCII-only keys enforced. */
export function canonicalize(obj: Record<string, unknown>): string;

/** SHA-256 hash of the canonical form. Returns lowercase hex. */
export function canonicalHash(obj: Record<string, unknown>): string;

// ── v1 Signing (backwards compatible) ───────────────────────────

/** Sign result from signArtifact / createSignedArtifact. */
export interface SignResult {
  artifact: Record<string, unknown> & { signature: string };
  signature: string;
  hash: string;
}

/** Sign a v1 artifact payload with Ed25519. Payload must include v, type, timestamp. */
export function signArtifact(
  payload: Record<string, unknown> & { v: number; type: string; timestamp: string },
  privateKeyHex: string,
): SignResult;

// ── v2 Signing (structured envelope) ────────────────────────────

/** Metadata for v2 artifact envelope. */
export interface ArtifactMeta {
  /** JWK thumbprint key identifier */
  kid: string;
  /** Issuer domain or DID */
  issuer: string;
  /** ISO 8601 timestamp (defaults to now) */
  issued_at?: string;
}

/** v2 artifact envelope structure (before signature). */
export interface ArtifactEnvelope {
  v: 2;
  type: string;
  algorithm: 'ed25519';
  kid: string;
  issuer: string;
  issued_at: string;
  payload: Record<string, unknown>;
  signature: string;
}

/** Create and sign a v2 artifact with structured envelope. */
export function createSignedArtifact(
  type: string,
  payload: Record<string, unknown>,
  privateKeyHex: string,
  meta: ArtifactMeta,
): SignResult;

// ── Unified Verification ────────────────────────────────────────

/** Verification result from verifyArtifact. */
export interface VerifyResult {
  valid: boolean;
  hash?: string;
  error?: string;
  /** Detected artifact version (1 or 2) */
  version?: number;
}

/** Verify an artifact's Ed25519 signature. Works for both v1 and v2. */
export function verifyArtifact(
  artifact: Record<string, unknown> & { signature: string },
  publicKeyHex: string,
): VerifyResult;

// ── JWK Thumbprint ──────────────────────────────────────────────

/** Compute a JWK thumbprint (RFC 7638) for an Ed25519 public key. Returns base64url. */
export function computeKid(publicKeyHex: string): string;

// ── Holder Binding ──────────────────────────────────────────────

/**
 * Compute a holder-binding commitment.
 * HBC = H("DS_holder_bind" || key_material || nonce)
 */
export function computeHolderBinding(keyMaterial: Uint8Array, nonce: Uint8Array): string;

// ── Public Key Utilities ────────────────────────────────────────

/** JWK representation of an Ed25519 public key. */
export interface Ed25519JWK {
  kty: 'OKP';
  crv: 'Ed25519';
  kid: string;
  x: string;
  use: 'sig';
}

/** Convert an Ed25519 public key to JWK format (RFC 8037). */
export function publicKeyToJWK(publicKeyHex: string, kid?: string): Ed25519JWK;

// ── Payload Validation ──────────────────────────────────────────

/** Validation result for artifact payloads. */
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

/** Validate a v2 artifact payload against its registered type schema. */
export function validatePayload(type: string, payload: Record<string, unknown>): ValidationResult;

// ── Trust Tiers ─────────────────────────────────────────────────

/** Trust tier values in ascending order of privilege. */
export type TrustTier = 'unknown' | 'signed-known' | 'evidenced' | 'privileged';

/** Ordered list of trust tiers. */
export const TRUST_TIERS: TrustTier[];

/** Compare two trust tiers. Returns negative if a < b, 0 if equal, positive if a > b. */
export function compareTiers(a: TrustTier, b: TrustTier): number;

/** Check if a tier meets a minimum tier requirement. */
export function meetsMinTier(actual: TrustTier, required: TrustTier): boolean;

// ── Keypair Utilities ───────────────────────────────────────────

/** Generate a new Ed25519 keypair with computed JWK thumbprint kid. */
export function generateKeypair(): { privateKey: string; publicKey: string; kid: string };

/** Derive public key from private key. */
export function getPublicKey(privateKeyHex: string): string;

// ── Base64url Utilities ─────────────────────────────────────────

/** Encode bytes as base64url (no padding). */
export function bytesToBase64url(bytes: Uint8Array): string;

/** Decode base64url string to bytes. */
export function base64urlToBytes(b64url: string): Uint8Array;

// ── Re-exports ──────────────────────────────────────────────────

export { bytesToHex, hexToBytes, utf8ToBytes } from '@noble/hashes/utils';
export { sha256 } from '@noble/hashes/sha256';
